CREATE POLICY "Own character reference uploads" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'character-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own character reference reads" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'character-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own character reference deletes" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'character-references' AND (storage.foldername(name))[1] = auth.uid()::text);